#!/bin/bash
# ==========================================================
# 终极 Web AI 编程工作站 - 一键全自动部署脚本 (Self-Contained)
# 核心组件: ShellFromBrowser (含 Web终端 30009 + Web网盘 30010 + Web VS Code 30011)
#           帮助与快捷键弹窗/智能 Cloudflare 子域名绑定/DOCX/XLSX/TXT 预览编辑/文件删除
#           FileBrowser网盘 + VS Code IDE + Tmux多Session同步 + Cloudflared穿透 + AGY/Claude/Codex
#           语音输入（浏览器原生 + 本机 faster-whisper 30022）
#           AI 说人话转命令（需 /root/.config/secrets/env 里的 ANTHROPIC_AUTH_TOKEN）
# 终端端口: 30009 | 网盘端口: 30010 | VS Code端口: 30011 | 语音后端: 30022
# 默认账号: admin | 默认密码: gjp
# ==========================================================

set -e

echo -e "\n\033[1;10] 正在清理旧环境与残留...\033[0m"
systemctl stop shellfb cf-tunnel filebrowser cf-filebrowser code-server cf-vscode 2>/dev/null || true
systemctl disable shellfb cf-tunnel filebrowser cf-filebrowser code-server cf-vscode 2>/dev/null || true
rm -rf /etc/shellfb /etc/filebrowser /etc/systemd/system/shellfb.service /etc/systemd/system/cf-tunnel.service /etc/systemd/system/filebrowser.service /etc/systemd/system/cf-filebrowser.service /etc/systemd/system/code-server.service /etc/systemd/system/cf-vscode.service

echo -e "\n\033[1;36m[2/10] 安装基础系统依赖 (含图形预览 chafa、文档转换 libreoffice、剪贴板与 Tmux 支持)...\033[0m"
export DEBIAN_FRONTEND=noninteractive
apt update && apt install -y curl wget git unzip openssl python3-bcrypt xclip wl-clipboard tmux chafa libreoffice

# 配置 tmux
cat > /root/.tmux.conf << 'EOF'
set -g mouse off
set -g allow-rename off
set -g history-limit 50000
set -g default-terminal "screen-256color"
set -g base-index 1
setw -g pane-base-index 1
set -g renumber-windows on
setw -g aggressive-resize on
EOF

# 写入 setname 重命名别名函数
cat >> /root/.bashrc << 'EOF'
setname() {
    if [ -z "$1" ]; then
        echo "使用方法: setname <项目或Session名称>"
        return 1
    fi
    export SESSION_TITLE="$1"
    if [ -n "$TMUX" ]; then
        tmux rename-window "$1" 2>/dev/null
    fi
    echo -e "\033[1;32m✅ 当前终端窗口已成功重命名为: \033[1;33m$1\033[0m"
}
alias rename='setname'

_update_prompt() {
    local TITLE_PREFIX=""
    if [ -n "$SESSION_TITLE" ]; then
        TITLE_PREFIX="\[\033[1;33m\]📌【$SESSION_TITLE】\[\033[0m\] "
    fi
    PS1="${TITLE_PREFIX}\[\033[1;32m\]\u@\h\[\033[0m\]:\[\033[1;34m\]\w\[\033[0m\]\$ "
}
if [[ ";$PROMPT_COMMAND;" != *"_update_prompt;"* ]]; then
    PROMPT_COMMAND="_update_prompt${PROMPT_COMMAND:+;$PROMPT_COMMAND}"
fi
EOF

# 创建多 Session 智能绑定脚本
cat > /usr/local/bin/tmux-web-shell << 'EOF'
#!/bin/bash
export PATH="/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin:/root/.local/bin:$PATH"
export TERM="xterm-256color"

if [ -n "$TMUX" ]; then
    exec /bin/bash
fi

MY_PID=$$
SHELLFB_PID=$(pgrep -x shellfb | head -n 1)

INDEX=1
if [ -n "$SHELLFB_PID" ]; then
    PIDS=$(pgrep -P "$SHELLFB_PID" -f tmux-web-shell | sort -n)
    CALC_IDX=1
    for pid in $PIDS; do
        if [ "$pid" -eq "$MY_PID" ]; then
            INDEX=$CALC_IDX
            break
        fi
        CALC_IDX=$((CALC_IDX + 1))
    done
fi

SESS_NAME="session${INDEX}"
if tmux has-session -t "$SESS_NAME" 2>/dev/null; then
    exec tmux attach-session -t "$SESS_NAME"
else
    exec tmux new-session -s "$SESS_NAME"
fi
EOF
chmod +x /usr/local/bin/tmux-web-shell

echo -e "\n\033[1;36m[3/10] 解压工程源码并配置 Go 编译环境...\033[0m"
mkdir -p /root/shellfb-src
if [ ! -f /root/shellfb-src/go.mod ]; then
    echo "正在解压内置项目最新源码至 /root/shellfb-src..."
    ARCHIVE_LINE=$(grep -a -n "^__SHELLFB_SRC_ARCHIVE__" "$0" | cut -d: -f1)
    tail -n +$((ARCHIVE_LINE + 1)) "$0" | base64 -d | tar -xz -C /root
fi

LATEST_GO=$(curl -s https://go.dev/VERSION?m=text | head -n1)
wget -q https://go.dev/dl/${LATEST_GO}.linux-amd64.tar.gz
rm -rf /usr/local/go
tar -C /usr/local -xzf ${LATEST_GO}.linux-amd64.tar.gz
rm -f ${LATEST_GO}.linux-amd64.tar.gz
export PATH=/usr/local/go/bin:$PATH

echo -e "\n\033[1;36m[4/10] 编译并安装 Web 终端 (ShellFromBrowser)...\033[0m"
export GOPATH=$HOME/go
export PATH=$PATH:$GOPATH/bin
cd /root/shellfb-src && /usr/local/go/bin/go build -o /usr/local/bin/shellfb ./cmd/shellfb
cd /root

# 生成配置
mkdir -p /etc/shellfb /root/transfers
JWT_SECRET=$(openssl rand -hex 32)
HASH=$(python3 -c 'import bcrypt; print(bcrypt.hashpw(b"gjp", bcrypt.gensalt()).decode())')

cat > /etc/shellfb/config.yaml << EOF
server:
  addr: "127.0.0.1:30009"
  tls:
    enabled: false
auth:
  enabled: true
  jwt_secret: "${JWT_SECRET}"
  users:
    - username: admin
      password_hash: "${HASH}"
shell:
  command: "/bin/bash"
  env:
    - "TERM=xterm-256color"
sessions:
  max_per_user: 20
  idle_timeout: "720h"
transfer:
  dir: "/root"
EOF
# Holds the JWT secret and the password hash -- keep it off other accounts.
chmod 600 /etc/shellfb/config.yaml

cat > /etc/systemd/system/shellfb.service << 'EOF'
[Unit]
Description=ShellFromBrowser Web Terminal
After=network.target

[Service]
Environment="PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin:/root/.local/bin"
ExecStart=/usr/local/bin/shellfb --config /etc/shellfb/config.yaml
Restart=always
RestartSec=5
User=root
WorkingDirectory=/root

[Install]
WantedBy=multi-user.target
EOF

# The AI "说人话转命令" endpoint needs an Anthropic credential. It is read from
# the environment, so source the secrets file (if present) at start. Keeping the
# key in one 600-mode file beats copying it into a systemd unit.
mkdir -p /etc/systemd/system/shellfb.service.d
cat > /etc/systemd/system/shellfb.service.d/10-ai-env.conf << 'EOF'
[Service]
ExecStart=
ExecStart=/bin/bash -c 'if [ -r /root/.config/secrets/env ]; then set -a; . /root/.config/secrets/env; set +a; fi; exec /usr/local/bin/shellfb --config /etc/shellfb/config.yaml'
EOF

echo -e "\n\033[1;36m[4b/10] 部署本机语音识别后端 (faster-whisper)...\033[0m"
apt install -y python3-pip ffmpeg
pip3 install --quiet faster-whisper flask flask-cors
# The embedded archive ships whisper_server.py inside the source tree; place it
# where the unit file expects it.
if [ -f /root/shellfb-src/deploy/whisper_server.py ] && [ ! -f /root/whisper_server.py ]; then
    cp /root/shellfb-src/deploy/whisper_server.py /root/whisper_server.py
fi

if [ ! -f /root/whisper_server.py ]; then
    echo "警告: /root/whisper_server.py 不存在，语音的『本机 Whisper』引擎将不可用。" >&2
    echo "      浏览器原生识别引擎仍可正常使用。" >&2
else
    cat > /etc/systemd/system/whisper-server.service << 'EOF'
[Unit]
Description=Whisper Voice Server
After=network.target

[Service]
Type=simple
User=root
WorkingDirectory=/root
ExecStart=/usr/bin/python3 /root/whisper_server.py
Restart=always

[Install]
WantedBy=multi-user.target
EOF
fi

echo -e "\n\033[1;36m[5/10] 安装并配置可视化 Web 网盘 (FileBrowser)...\033[0m"
wget -q https://github.com/filebrowser/filebrowser/releases/download/v2.32.0/linux-amd64-filebrowser.tar.gz
tar -xzf linux-amd64-filebrowser.tar.gz && mv filebrowser /usr/local/bin/ && rm -f linux-amd64-filebrowser.tar.gz LICENSE README.md
mkdir -p /etc/filebrowser
filebrowser config init -a "127.0.0.1" -p 30010 -r "/root" -d "/etc/filebrowser/filebrowser.db" > /dev/null 2>&1
filebrowser users add admin gjp --perm.admin -d "/etc/filebrowser/filebrowser.db" > /dev/null 2>&1

cat > /etc/systemd/system/filebrowser.service << 'EOF'
[Unit]
Description=FileBrowser Web File Manager
After=network.target

[Service]
ExecStart=/usr/local/bin/filebrowser -d /etc/filebrowser/filebrowser.db
Restart=always
RestartSec=5
User=root
WorkingDirectory=/root

[Install]
WantedBy=multi-user.target
EOF

echo -e "\n\033[1;36m[6/10] 安装并配置全功能 Web VS Code IDE (code-server)...\033[0m"
curl -fsSL https://code-server.dev/install.sh | sh > /dev/null 2>&1 || true
mkdir -p /root/.config/code-server
cat > /root/.config/code-server/config.yaml << 'EOF'
bind-addr: 127.0.0.1:30011
auth: password
password: gjp
cert: false
EOF

cat > /etc/systemd/system/code-server.service << 'EOF'
[Unit]
Description=code-server Web IDE
After=network.target

[Service]
Type=simple
User=root
WorkingDirectory=/root
ExecStart=/usr/bin/code-server --config /root/.config/code-server/config.yaml /root
Restart=always
RestartSec=5

[Install]
WantedBy=multi-user.target
EOF

echo -e "\n\033[1;36m[7/10] 安装并配置 Cloudflare 官方穿透隧道...\033[0m"
curl -L -o cloudflared.deb https://github.com/cloudflare/cloudflared/releases/latest/download/cloudflared-linux-amd64.deb
dpkg -i cloudflared.deb > /dev/null 2>&1
rm -f cloudflared.deb

# Web 终端隧道
cat > /etc/systemd/system/cf-tunnel.service << 'EOF'
[Unit]
Description=Cloudflare Quick Tunnel for ShellFB
After=network.target

[Service]
ExecStart=/usr/bin/cloudflared tunnel --no-autoupdate --url http://127.0.0.1:30009
Restart=always
RestartSec=5

[Install]
WantedBy=multi-user.target
EOF

# FileBrowser 网盘隧道
cat > /etc/systemd/system/cf-filebrowser.service << 'EOF'
[Unit]
Description=Cloudflare Quick Tunnel for FileBrowser
After=network.target

[Service]
ExecStart=/usr/bin/cloudflared tunnel --no-autoupdate --url http://127.0.0.1:30010
Restart=always
RestartSec=5

[Install]
WantedBy=multi-user.target
EOF

# VS Code IDE 隧道
cat > /etc/systemd/system/cf-vscode.service << 'EOF'
[Unit]
Description=Cloudflare Quick Tunnel for Code-Server
After=network.target

[Service]
ExecStart=/usr/bin/cloudflared tunnel --no-autoupdate --url http://127.0.0.1:30011
Restart=always
RestartSec=5

[Install]
WantedBy=multi-user.target
EOF

echo -e "\n\033[1;36m[8/10] 部署 AI 编程神器与 Node.js 运行环境...\033[0m"
curl -fsSL https://deb.nodesource.com/setup_22.x | bash - > /dev/null 2>&1
apt install -y nodejs > /dev/null 2>&1

curl -fsSL https://antigravity.google/cli/install.sh | bash > /dev/null 2>&1 || true
npm install -g @anthropic-ai/claude-code > /dev/null 2>&1 || true
curl -fsSL https://chatgpt.com/codex/install.sh | sh > /dev/null 2>&1 || true

echo -e "\n\033[1;36m[9/10] 强制全局注册命令，确保网页终端 100% 秒开...\033[0m"
ln -sf /root/.local/bin/agy /usr/bin/agy 2>/dev/null || true
ln -sf /root/.local/bin/codex /usr/bin/codex 2>/dev/null || true
ln -sf $(which claude 2>/dev/null) /usr/bin/claude 2>/dev/null || true

# restart-all: the one-shot reset the README tells people to use. It used to
# exist only on the machine it was hand-written on, and it restarted
# "cloudflared cf-filebrowser" -- missing the terminal and IDE tunnels.
cat > /usr/local/bin/restart-all << 'EOF'
#!/bin/bash
set -u

restart() {
    local svc="$1" label="$2"
    printf '===> 正在重启 %s (%s)...\n' "$label" "$svc"
    if ! systemctl restart "$svc" 2>/dev/null; then
        printf '     [跳过] %s 未安装或重启失败\n' "$svc"
    fi
}

restart shellfb        "Web 终端"
restart whisper-server "语音识别后端"
restart filebrowser    "Web 网盘"
restart code-server    "Web IDE"

echo "===> 正在重启 Cloudflare 穿透隧道..."
for t in cf-tunnel cf-filebrowser cf-vscode; do
    restart "$t" "穿透隧道"
done

echo
echo "===> 完成。当前状态："
for s in shellfb whisper-server filebrowser code-server cf-tunnel cf-filebrowser cf-vscode; do
    printf '  %-16s %s\n' "$s" "$(systemctl is-active "$s" 2>/dev/null || echo 'not-installed')"
done

echo
echo "===> 访问链接（隧道地址需数秒生成）："
for pair in "cf-tunnel:Web 终端" "cf-filebrowser:Web 网盘" "cf-vscode:Web IDE"; do
    svc="${pair%%:*}"; label="${pair#*:}"
    url=$(journalctl -u "$svc" -n 50 --no-pager 2>/dev/null |
          grep -oE 'https://[a-zA-Z0-9-]+\.trycloudflare\.com' | tail -1)
    printf '  %-10s %s\n' "$label" "${url:-（暂无，稍后重试）}"
done
EOF
chmod +x /usr/local/bin/restart-all

echo -e "\n\033[1;36m[10/10] 正在拉起所有服务，并生成安全域名...\033[0m"
systemctl daemon-reload
systemctl enable --now shellfb cf-tunnel filebrowser cf-filebrowser code-server cf-vscode
# Only enable whisper if its script was shipped alongside this installer.
[ -f /root/whisper_server.py ] && systemctl enable --now whisper-server || true

echo -e "\n============================================="
echo "✅ 部署已全部完成！"
echo -e "🔗 Web终端专属域名: \033[1;32m$URL\033[0m"
echo -e "📁 Web网盘专属域名: \033[1;32m$FB_URL\033[0m"
echo -e "💻 Web VS Code 专属: \033[1;32m$VS_URL\033[0m"
echo -e "🔑 统一登录账号: \033[1;32madmin\033[0m"
echo -e "🔑 统一登录密码: \033[1;32mgjp\033[0m"
echo -e "\n🤖 三大 AI 助手已就绪:"
echo -e "   - \033[1;33magy\033[0m    (Google Antigravity)"
echo -e "   - \033[1;33mclaude\033[0m (Anthropic Claude Code)"
echo -e "   - \033[1;33mcodex\033[0m  (OpenAI Codex CLI)"
echo "============================================="

exit 0
__SHELLFB_SRC_ARCHIVE__

